service.method:

UPDATE SLANG
   SET CONTENTS       = ${CONTENTS}           
  	  ,CHANGE_USER_ID = ${session.ID}       
  	  ,CHANGE_DATE    = ${current.DATE}     
  	  ,CHANGE_TIME    = ${current.TIME}     
  	  ,DEL_FLAG       = 'N'
 WHERE HOUSE_CODE     = ${session.HOUSE_CODE} 
   AND SCREEN_ID      = ${SCREEN_ID}          
   AND LANGUAGE       = ${session.LANGUAGE}
   AND CODE           = ${CODE}


SELECT COUNT(*) CNT
  FROM SLANG 
 WHERE HOUSE_CODE     = ${session.HOUSE_CODE} 
   AND SCREEN_ID      = ${SCREEN_ID}          
   AND LANGUAGE       = ${session.LANGUAGE}
   AND CODE           = ${CODE}


DELETE
  FROM SCMAM
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${COMPANY_CODE}


SELECT MODULE 
      ,OPTION
  FROM SCMAM
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${COMPANY_CODE}
